#include "notify/formatting.hpp"
#include "notify/json.hpp"
#include <windows.h>
#include <algorithm>
#include <regex>
#include <fstream>
#include <stdexcept>
#include <filesystem>
#include <cstring>
#include <vector>
namespace notify {
std::string escape_text(std::string_view s,std::string_view style){if(style!="plain"&&style!="html"&&style!="markdown_v2")throw std::runtime_error("unsupported parse style");std::string o;for(char c:s){if(style=="html"){if(c=='&')o+="&amp;";else if(c=='<')o+="&lt;";else if(c=='>')o+="&gt;";else o+=c;}else if(style=="markdown_v2"&&std::string_view("_*[]()~`>#+-=|{}.!\\").find(c)!=std::string_view::npos){o+='\\';o+=c;}else o+=c;}return o;}
std::vector<Entity> parse_entities(std::string_view s,std::string_view){std::vector<Entity> v;std::string t(s);static const std::regex re(R"(@([A-Za-z0-9_]{5,})|tg://user\?id=([0-9]+))");for(std::sregex_iterator i(t.begin(),t.end(),re),e;i!=e;++i){auto m=*i;v.push_back({m[1].matched?EntityType::mention:EntityType::text_mention,(size_t)m.position(),(size_t)m.length(),m[1].matched?m[1].str():m[2].str()});}return v;}
std::string plain_with_mentions_html(std::string_view input){const std::string text(input);const auto entities=parse_entities(input,"plain");std::string out;std::size_t cursor=0;for(const auto& entity:entities){if(entity.offset<cursor||entity.offset>text.size()||entity.length>text.size()-entity.offset)continue;out+=escape_text(std::string_view(text).substr(cursor,entity.offset-cursor),"html");const auto label=std::string_view(text).substr(entity.offset,entity.length);if(entity.type==EntityType::mention){const auto username=label.substr(1);out+="<a href=\"https://t.me/"+std::string(username)+"\">"+escape_text(label,"html")+"</a>";}else{const auto target="tg://user?id="+entity.value;out+="<a href=\""+target+"\">"+escape_text(label,"html")+"</a>";}cursor=entity.offset+entity.length;}out+=escape_text(std::string_view(text).substr(cursor),"html");return out;}
std::string entities_json(const std::vector<Entity>& entities){json::Value::Array list;for(const auto&e:entities){std::string type;switch(e.type){case EntityType::mention:type="mention";break;case EntityType::text_mention:type="text_mention";break;case EntityType::bold:type="bold";break;case EntityType::italic:type="italic";break;case EntityType::code:type="code";break;case EntityType::url:type="text_link";break;case EntityType::custom_emoji:type="custom_emoji";break;}json::Value::Object item;item["type"].data=type;item["offset"].data=(std::int64_t)e.offset;item["length"].data=(std::int64_t)e.length;if(e.type==EntityType::url)item["url"].data=e.value;if(e.type==EntityType::custom_emoji)item["custom_emoji_id"].data=e.value;json::Value v;v.data=std::move(item);list.push_back(std::move(v));}json::Value v;v.data=std::move(list);return json::stringify(v);}
void validate_post(const Post&p,const BuildConfig&c){if(!p.entities.empty()&&p.entity_unit_state==State::unset)throw std::runtime_error("entity_unit unset; refusing to send entities");if(p.style!="plain"&&p.style!="html"&&p.style!="markdown_v2")throw std::runtime_error("invalid style");for(auto&e:p.entities){if(e.type==EntityType::custom_emoji&&!c.is_set("custom_emoji_document_id"))throw std::runtime_error("custom_emoji unset");if(e.offset>p.text.size()||e.length>p.text.size()-e.offset)throw std::runtime_error("entity range invalid");}}
bool validate_photo(const std::wstring&path,size_t limit){HANDLE h=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER sz{};if(!GetFileSizeEx(h,&sz)||sz.QuadPart<12||(unsigned long long)sz.QuadPart>limit){CloseHandle(h);return false;}std::vector<unsigned char>b((size_t)sz.QuadPart);size_t pos=0;while(pos<b.size()){DWORD got=0,ask=(DWORD)(std::min)(b.size()-pos,(size_t)1<<20);if(!ReadFile(h,b.data()+pos,ask,&got,nullptr)||got==0){CloseHandle(h);return false;}pos+=got;}CloseHandle(h);return (b[0]==0xff&&b[1]==0xd8&&b[2]==0xff)||(b.size()>=8&&memcmp(b.data(),"\x89PNG\r\n\x1a\n",8)==0)||(b.size()>=12&&memcmp(b.data(),"RIFF",4)==0&&memcmp(b.data()+8,"WEBP",4)==0);}
std::vector<Subscriber> read_subscribers(const std::wstring&path){std::ifstream f(std::filesystem::path(path),std::ios::binary);std::vector<Subscriber> out;if(!f)return out;std::string line;size_t total=0;while(std::getline(f,line)){total+=line.size();if(total>4*1024*1024)throw std::runtime_error("subscriber file limit");if(line.empty())continue;auto j=json::parse(line,65536,16);auto a=j.find("chat_id"),b=j.find("consent_ts"),c=j.find("source");if(!a||!b||!c||b->string_or().empty()||c->string_or().empty())continue;auto id=a->string_or();if(id.empty()){if(auto n=std::get_if<std::int64_t>(&a->data))id=std::to_string(*n);else throw std::runtime_error("invalid chat_id type");}out.push_back({id,b->string_or(),c->string_or()});if(out.size()>100000)throw std::runtime_error("subscriber count limit");}if(!f.eof())throw std::runtime_error("partial subscriber read");return out;}
}
